    startDate: '2027-02-14T18:30:00-05:00',
    endDate: '2027-02-14T22:30:00-05:00',
    description: 'The biggest single-day sporting event in America returns to Los Angeles as SoFi Stadium hosts Super Bowl LXI on Valentine\'s Day Sunday, February 14, 2027.',
    priceEstimate: '$4,000 – $12,000',
    price: { travel: { min: 4000, max: 12000 }, flight: { min: 400, max: 1000 }, hotel: { min: 300, max: 300, unit: 'night' }, ticket: { min: 3000, max: 10000 } },
    colorFrom: '#78350f',
